{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
}

// Now try a type whose metadata may NOT be available (custom resolver that
// only knows about Person).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// DefaultJsonTypeInfoResolver resolves any type, so let's use a resolver
// that deliberately resolves nothing to show the "not available" branch.
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (empty.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
{
    Console.WriteLine($"Unexpected: resolved {missing!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> on empty resolver: not available (no exception thrown)");
}

public record Person(string Name, int Age);

/// A resolver that resolves nothing — simulates missing metadata.
file sealed class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}
